double TripletScore::evaluate_indexes(Model *m,
                                        const ParticleIndexTriplets &o,
                                        DerivativeAccumulator *da,
                                        unsigned int lower_bound,
                                        unsigned int upper_bound, bool) const {
  double ret = 0;
  for (unsigned int i = lower_bound; i < upper_bound; ++i) {
    ret += evaluate_index(m, o[i], da);
  }
  return ret;
}

double TripletScore::evaluate_indexes_scores(
                Model *m, const ParticleIndexTriplets &p,
                DerivativeAccumulator *da, unsigned int lower_bound,
                unsigned int upper_bound,
                std::vector<double> &score, bool) const {
  double ret = 0;
  for (unsigned int i = lower_bound; i < upper_bound; ++i) {
    double s = evaluate_index(m, p[i], da);
    score[i] = s;
    ret += s;
  }
  return ret;
}

double TripletScore::evaluate_indexes_delta(
                Model *m, const ParticleIndexTriplets &p,
                DerivativeAccumulator *da,
                const std::vector<unsigned> &indexes,
                std::vector<double> &score, bool) const {
  double ret = 0;
  for (std::vector<unsigned>::const_iterator it = indexes.begin();
       it != indexes.end(); ++it) {
    double s = evaluate_index(m, p[*it], da);
    ret = ret - score[*it] + s;
    score[*it] = s;
  }
  return ret;
}

double TripletScore::evaluate_if_good_index(Model *m,
                                              const ParticleIndexTriplet& vt,
                                              DerivativeAccumulator *da,
                                              double max) const {
  IMP_UNUSED(max);
  return evaluate_index(m, vt, da);
}

double TripletScore::evaluate_if_good_indexes(
    Model *m, const ParticleIndexTriplets &o, DerivativeAccumulator *da,
    double max, unsigned int lower_bound, unsigned int upper_bound,
    bool) const {
  double ret = 0;
  for (unsigned int i = lower_bound; i < upper_bound; ++i) {
    double cur = evaluate_if_good_index(m, o[i], da, max - ret);
    max -= cur;
    ret += cur;
    if (max < 0) break;
  }
  return ret;
}

Restraints TripletScore::do_create_current_decomposition(
    Model *m, const ParticleIndexTriplet& vt) const {
  double score = evaluate_index(m, vt, nullptr);
  if (score == 0) {
    return Restraints();
  } else {
    Pointer<Restraint> ret = IMP::internal::create_tuple_restraint
      (this, m, vt, get_name());
    ret->set_last_score(score);
    return Restraints(1, ret);
  }
}

Restraints TripletScore::create_current_decomposition(
    Model *m, const ParticleIndexTriplet& vt) const {
  return do_create_current_decomposition(m, vt);
}

